document.addEventListener('DOMContentLoaded',function(){"use strict";window.addEventListener('load',function(){const loader=document.querySelector('.br-loader');if(loader){loader.style.transition='opacity 0.5s ease';loader.style.opacity='0';setTimeout(()=>loader.style.display='none',500);}});let b=0;const progress=document.getElementById('about');window.addEventListener('scroll',function(){if(progress){const oTop=progress.getBoundingClientRect().top+window.scrollY-window.innerHeight;if(b===0&&window.scrollY>oTop){const max=-219.99078369140625;document.querySelectorAll('.progress').forEach(function(value){const percent=value.getAttribute('data-progress');const fill=value.querySelector('.fill');const valueEl=value.querySelector('.value');if(fill)fill.setAttribute('style','stroke-dashoffset: '+((100-percent)/100)*max);if(valueEl)valueEl.innerHTML=percent+'%';});b=1;}}});if(!window.__indexSidebar){const toggleBtn=document.querySelector('.br-sidebar-toggle');const sidebar=document.querySelector('.br-sidebar');const overlay=document.querySelector('.br-sidebar-overlay');if(toggleBtn&&sidebar&&overlay){toggleBtn.addEventListener('click',function(){const isOpen=sidebar.classList.contains('br-open');if(isOpen){sidebar.classList.remove('br-open','br-sidebar-open');overlay.style.display='none';}else{sidebar.classList.add('br-open','br-sidebar-open');overlay.style.display='block';}});document.querySelectorAll('.close-sidebar, .nav-link.br-nav').forEach(el=>{el.addEventListener('click',function(){sidebar.classList.remove('br-open','br-sidebar-open');overlay.style.display='none';});});overlay.addEventListener('click',function(){sidebar.classList.remove('br-open','br-sidebar-open');overlay.style.display='none';});}}
const portfolioContent=document.querySelector('.portfolio-content');if(portfolioContent&&typeof mixitup!=='undefined'){mixitup(portfolioContent);}
document.querySelectorAll('img.svg_img[src$=".svg"]').forEach(function(img){const imgID=img.id;const imgClass=img.className;const imgURL=img.src;fetch(imgURL).then(response=>response.text()).then(data=>{const parser=new DOMParser();const xmlDoc=parser.parseFromString(data,'text/xml');let svg=xmlDoc.getElementsByTagName('svg')[0];if(svg){if(typeof imgID!=='undefined'){svg.setAttribute('id',imgID);}
if(typeof imgClass!=='undefined'){svg.setAttribute('class',imgClass+' replaced-svg');}
svg.removeAttribute('xmlns:a');img.replaceWith(svg);}});});document.querySelectorAll('.scroll-next').forEach(function(el){el.addEventListener('click',function(e){e.preventDefault();const targetHref=this.getAttribute('data-scroll');if(targetHref){const target=document.getElementById(targetHref.replace('#',''));if(target){target.scrollIntoView({behavior:'smooth'});}}});});const sections=document.querySelectorAll('section');const navLinks=document.querySelectorAll('.navbar-nav .nav-link');window.addEventListener('scroll',()=>{let current='';sections.forEach(section=>{const sectionTop=section.offsetTop;const sectionHeight=section.clientHeight;if(scrollY>=(sectionTop-sectionHeight/3)){current=section.getAttribute('id');}});navLinks.forEach(link=>{if(link.parentElement){link.parentElement.classList.remove('active');}
if(link.getAttribute('href')==='#'+current&&link.parentElement){link.parentElement.classList.add('active');}});});const menu=document.querySelector('.menu');const circle=document.querySelector('.circle');const textEl=document.querySelector('.text');if(menu&&circle&&typeof TweenMax!=='undefined'){menu.addEventListener('mousemove',function(e){const rect=circle.getBoundingClientRect();const circleLeft=rect.left+window.pageXOffset;const circleTop=rect.top+window.pageYOffset;const s=e.pageX-circleLeft;const o=e.pageY-circleTop;TweenMax.to(circle,0.3,{x:(s-rect.width/2)/rect.width*50,y:(o-rect.height/2)/rect.height*50,scale:1.2,ease:Power2.easeOut});if(textEl){TweenMax.to(textEl,0.3,{x:(s-rect.width/2)/rect.width*80,y:(o-rect.height/2)/rect.height*80,ease:Power2.easeOut});}});menu.addEventListener('mouseleave',function(e){TweenMax.to(circle,0.3,{x:0,y:0,scale:1,ease:Power2.easeOut});if(textEl){TweenMax.to(textEl,0.3,{x:0,y:0,ease:Power2.easeOut});}});}});if('scrollRestoration'in history){history.scrollRestoration='manual';}
window.addEventListener('beforeunload',()=>{sessionStorage.setItem('scrollPosition',window.scrollY);});window.addEventListener('load',()=>{const scrollPos=sessionStorage.getItem('scrollPosition');if(scrollPos!==null){setTimeout(()=>{window.scrollTo({top:parseInt(scrollPos,10),behavior:'auto'});sessionStorage.removeItem('scrollPosition');},50);}});;